// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "Test", "TST"); }
    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerInitialBalance = c.balanceOf(address(this));
        vm.assume(burnAmount > 0 && burnAmount <= ownerInitialBalance);

        uint256 initialTotalSupply = c.totalSupply();

        c.burn(burnAmount);

        assertTrue(c.totalSupply() == initialTotalSupply - burnAmount);
    }
}
